Go through the list once, keeping the length of the current run and the longest run seen so far. Compare neighbours with .equals, not == on Integer objects.

public static int longestRun(ArrayList<Integer> data) {
    if (data.size() == 0) return 0;
    int max = 1, cur = 1;
    for (int i = 1; i < data.size(); i++) {
        if (data.get(i).equals(data.get(i - 1))) {
            cur++;
        } else {
            cur = 1;
        }
        if (cur > max) max = cur;
    }
    return max;
}

